mapper.select:
        select  t.tel1,t.tel2,t.machine_id,t.machine_id machineId,t.create_time,t.create_time createTime,t.status_cd,t.status_cd statusCd,t.id,t.tel3,t.tel4 
from work_license_white_list t 
where 1 =1 

   and t.tel1= #{tel1}


   and t.tel2= #{tel2}


   and t.machine_id= #{machineId}


   and t.create_time= #{createTime}


   and t.status_cd= #{statusCd}


   and t.id= #{id}


   and t.tel3= #{tel3}


   and t.tel4= #{tel4}

order by t.create_time desc

   limit #{page}, #{row}

